INSERT INTO manual_entries (manual_id, type, code, level, title, detection, causes, solution, description, setting) VALUES
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC722-70$m$, $m$B$m$, $m$Finisher tray 1 (upper tray lift) motor error (D610)$m$, $m$The upper tray paper height sensor does not change its status with the specified time after the tray raises or lowers. The 1st detection failure issues a jam error, and the 2nd failure issues this SC code.$m$, $m$Tray lift motor disconnected, defective · Upper tray paper height sensor disconnected, defective · Finisher main board connection to motor loose · Finisher main board defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC722-71$m$, NULL, $m$Shift Motor Error (D610)$m$, $m$The shift tray half-turn sensors:$m$, $m$D Failed twice to detect the shift tray at the home position at the · specified time. · -or- · Failed twice to detect that the shift tray had left the home position. · If the motor is operating · Half-turn sensor 1, 2 harnesses loose, broken, defective · One of the half-turn sensors is defective · If the motor is not operating: · Motor blocked by an obstruction · Motor harness loose, broken, defective · Motor defective · Finisher main board defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC722-72$m$, $m$B$m$, $m$Front shift jogger motor error (D610)$m$, $m$The sides fences do not retract within the prescribed time after the shift jogger motor switches on. The 1st detection failure issues a jam error, and the 2nd failure issues this SC code.$m$, $m$Shift jogger motor disconnected, defective · Shift jogger motor overloaded due to obstruction · Shift jogger HP sensor disconnected, defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC722-74$m$, $m$B$m$, $m$Shift jogger retraction motor error (D610)$m$, $m$The side fences do not retract within the prescribed time after the retraction motor switches on. The 1st detection failure issues a jam Service Call error, and the 2nd failure issues this SC code. Conditions Motor harness disconnected, loose, defective$m$, $m$Motor defective · Motor overload · HP defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC722-75$m$, $m$B$m$, $m$Return roller motor error (D610)$m$, $m$Occurs during the operation of the lower tray pressure motor.$m$, $m$Motor harness disconnected, loose, defective · Motor overloaded · Home position sensor harness disconnected, loose, defective · Home position defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC722-80$m$, $m$B$m$, $m$Finisher staple trimming hopper full (D610)$m$, $m$The staple waste hopper is full of cut staples. If the hopper is full, empty the hopper If the hopper is not full, the hopper full sensor is disconnected,$m$, $m$defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC722-81$m$, $m$D$m$, $m$Finisher transport motor error (D610)$m$, $m$The encoder pulse of the finisher transport motor does not change state (high/low) within 600 ms and does not change after 2 retries.$m$, $m$Finisher transport motor defective · Transport motor harness disconnected, or defective · Finisher main board defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC722-83$m$, $m$D$m$, $m$Finisher punch motor error (D610)$m$, $m$The punch HP sensor is not activated within the specified time after the punch motor turned on. The 1st detection failure issues a jam error, and the 2nd failure issues this SC code.$m$, $m$Punch HP sensor disconnected, defective · Punch motor disconnected, defective · Punch motor overload due to obstruction$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC724-71$m$, NULL, $m$Shift Motor Error$m$, $m$The shift tray half-turn sensors:$m$, $m$D Failed twice to detect the shift tray at the home position at the · specified time. · -or- · Failed twice to detect that the shift tray had left the home position. · If the motor is operating · Half-turn sensor 1, 2 harnesses loose, broken, defective · One of the half-turn sensors is defective · If the motor is not operating: · Motor blocked by an obstruction · Motor harness loose, broken, defective · Motor defective · Finisher main board defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC725-01$m$, NULL, $m$Downstream finisher communication error (D615)$m$, $m$No response signal was received from the downstream finisher D (D615) after 3 attempts$m$, $m$Finisher I/F cable loose, broken defective · Finisher control board defective · Reg. Roller Transport Motor Error Multi Folder (D615)$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC725-12$m$, $m$B$m$, $m$The motor drive PCB detected an error at the motor.$m$, $m$Motor harness or connector loose, broken, defective Service Call Motor or motor drive board defective Conditions Dynamic Roller Transport Motor Error Multi Folder (D615)$m$, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC725-13$m$, $m$B$m$, $m$The motor drive PCB detected an error at the motor.$m$, $m$Motor harness or connector loose, broken, defective$m$, $m$Motor or motor drive board defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC725-14$m$, $m$B$m$, $m$Z-fold top tray exit motor error$m$, $m$The motor driver detects an error.$m$, $m$Motor over current · Motor driver overheat$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC725-30$m$, NULL, $m$Z-fold stopper 1 Motor error$m$, $m$The bottom fence HP sensor detected that: The bottom fence did not arrive at the home position at the B specified time.$m$, $m$-or- · The bottom fence failed to leave the home position at the specified · time. · Motor over-current · Motor driver overheat · Motor harness loose · 2nd Stopper Motor Error Multi Folder (D615)$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC725-31$m$, NULL, $m$The 2nd stopper HP sensor did not detect the 2nd stopper in (or$m$, $m$out of) its home position within the prescribed time. The 1st occurrence causes a jam, and the 2nd occurrence causes this SC code.$m$, $m$B · 2nd stopper HP sensor dirty · Sensor harness or connector loose, broken, defective · 2nd stopper motor harness or connector loose, broken, · defective · Sensor defective · Motor or motor drive board defective · 3rd Stopper Motor Error Multi Folder (D615) · The 3rd stopper HP sensor did not detect the 3rd stopper in (or out · of) its home position within the prescribed time. The 1st occurrence · causes a jam, and the 2nd occurrence causes this SC code.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC725-32$m$, $m$B$m$, $m$3rd stopper HP sensor dirty$m$, $m$Sensor harness or connector loose, broken, defective 3rd stopper motor harness or connector loose, broken, defective$m$, $m$Sensor defective · Motor or motor drive board defective · Jogger Fence Motor Multi Folder (D615)$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC725-33$m$, NULL, $m$The jogger fence HP sensor did not detect the jogger fence in (or$m$, $m$out of) its home position within the prescribed time. The 1st Service Call occurrence causes a jam, and the 2nd occurrence causes this SC Conditions code.$m$, $m$B · Jogger fence HP sensor dirty · Sensor harness or connector loose, broken, defective · Jogger fence motor harness or connector loose, broken, · defective · Sensor defective · Motor or motor drive board defective · Dynamic Roller Lift Motor Error Multi Folder (D615)$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC725-34$m$, NULL, $m$The dynamic roller HP sensor did not detect the dynamic roller in$m$, $m$(or out of) its home position within the prescribed time. The 1st occurrence causes a jam, and the 2nd occurrence causes this SC code.$m$, $m$B · Dynamic roller HP sensor dirty · Sensor harness or connector loose, broken, defective · Dynamic roller lift motor harness or connector loose, broken, · defective · Sensor defective · Motor or motor drive board defective · Registration Roller Release Motor Error Multi Folder (D615)$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC725-35$m$, NULL, $m$The registration roller HP sensor did not detect the registration$m$, $m$roller in (or out of) its home position within the prescribed time. The 1st occurrence causes a jam, and the 2nd occurrence causes this SC code.$m$, $m$B · Registration roller HP sensor dirty · Sensor harness or connector loose, broken, defective · Registration roller release motor harness or connector loose, · broken, defective · Sensor defective · Motor or motor drive board defective · FM2 Direct-Send JG Motor Multi Folder (D615)$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC725-36$m$, NULL, $m$The direct-send JG HP sensor did not detect the direct-send JG in$m$, $m$(or out of) its home position within the prescribed time. The 1st occurrence causes a jam, and the 2nd occurrence causes this SC code.$m$, $m$B · FM2 direct-send JG HP sensor dirty · Sensor harness or connector loose, broken, defective · FM2 direct-send JG motor harness or connector loose, · broken, defective · Sensor defective · Motor or motor drive board defective · FM6 Pawl Motor Multi Folder (D615) · The FM6 pawl HP sensor did not detect the FM6 pawl in (or out · of) its home position. The 1st occurrence causes a jam, and the · 2nd occurrence causes this SC code.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC725-37$m$, $m$B$m$, $m$FM6 pawl HP sensor dirty$m$, $m$Sensor harness or connector loose, broken, defective Service Call FM6 pawl motor harness or connector loose, broken, Conditions defective$m$, $m$Sensor defective · Motor or motor drive board defective · Fold Plate Motor Error Multi Folder (D615) · The fold plate HP sensor did not detect the fold plate in (or out of) · its home position within the prescribed time. The 1st occurrence · causes a jam, and the 2nd occurrence causes this SC code.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC725-38$m$, $m$B$m$, $m$Fold plate HP sensor dirty$m$, $m$Sensor harness or connector loose, broken, defective Fold plate motor harness or connector loose, broken, defective$m$, $m$Sensor defective · Motor or motor drive board defective · 1st Fold Motor Error Multi Folder (D615)$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC783-3$m$, $m$B$m$, $m$The motor drive PCB detected an error at the motor.$m$, $m$Motor harness or connector loose, broken, defective Motor or motor drive board defective$m$, $m$2nd Fold Motor Error Multi Folder (D615)$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC783-4$m$, $m$B$m$, $m$The motor drive PCB detected an error at the motor.$m$, $m$Motor harness or connector loose, broken, defective Motor or motor drive board defective$m$, $m$Crease Motor Error Multi Folder (D615)$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC725-41$m$, $m$B$m$, $m$The motor drive PCB detected an error at the motor.$m$, $m$Motor harness or connector loose, broken, defective Motor or motor drive board defective$m$, $m$Horizontal Transport Motor Error Multi Folder (D615)$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC725-71$m$, $m$D$m$, $m$The motor drive PCB detected an error at the motor.$m$, $m$Motor harness or connector loose, broken, defective Motor or motor drive board defective$m$, $m$Horizontal exit motor error$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC725-72$m$, $m$D$m$, $m$An error occurred on the motor drive board.$m$, $m$Motor current overload$m$, $m$Motor drive board defective (replace motor) · Top Tray Exit Motor Multi Folder (D615)$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC725-73$m$, $m$D$m$, $m$The motor drive PCB detected an error at the motor.$m$, $m$Motor harness or connector loose, broken, defective Motor or motor drive board defective$m$, $m$Entrance JG Motor Multi Folder (D615) · The entrance junction gate HP sensor did not detect the entrance · junction gate at (or out of) its home position. The 1st occurrence · causes a jam, and the 2nd occurrence causes this SC code.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC725-74$m$, $m$D$m$, $m$Entrance JG HP sensor dirty$m$, $m$Sensor harness or connector loose, broken, defective Service Call Entrance JG motor harness or connector loose, broken, Conditions defective$m$, $m$Sensor defective · Motor or motor drive board defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC740-10$m$, NULL, $m$Cover interposer tray bottom plate motor error$m$, $m$After the motor starts to raise the bottom plate, the bottom plate B position sensor does not detect the plate at the specified time (3 s). After the motor starts to lower the bottom plate, the bottom plate HP sensor does not detect the bottom plate.$m$, $m$Bottom plate position sensor, disconnected, defective · Bottom plate HP sensor disconnected, defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC816$m$, $m$D$m$, $m$Energy save I/O subsystem error$m$, $m$The energy save I/O subsystem is defective or this system detected a controller board error. Reboot the machine.$m$, NULL, $m$Replace the controller board. Monitor error GW$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC817$m$, NULL, $m$This is a file detection and electronic file signature check error$m$, $m$when the boot loader attempts to read the self-diagnostic module, system kernel, or root system files from the OS Flash ROM, or the D items on the SD card in the controller slot are false or corrupted.$m$, $m$OS Flash ROM data defective · SD card data defective$m$, $m$1. Change the controller firmware. 2. Use another SD card. Error Codes Code Meaning 0x0000 0000 BIOS boot error 0x0000 0001 Primary boot start load error 0x0000 0002 Secondary boot load error (Boot3.Elf) 0x0000 0003 Self-diagnostic module error (Diag.Elf) 0x0000 0004 Kernel start error (Netbsd) 0x0000 0005 Root file system file read error (Rootfs) 0xffff ffff Other error Example: Data in the self-diagnostic module, system kernel, or root system files are corrupted or do not exist in OS flash ROM or on the SD card Service Call Files in the self-diagnostic module, kernel, or root file system on the SD card have been falsified Conditions or altered Before discarding the SD card, try to update the data on the card. If the error occurs again, the card may be defective. Be sure to use an SD card that contains the correct electronic signature. Fatal kernel error Due to a control error, a RAM overflow occurred during system processing. One of the following messages was displayed on the operation panel. 0x5032 HAIC-P2 error$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC819$m$, $m$D$m$, $m$0x5245 Link-up fail$m$, $m$L2 Status Time Out$m$, $m$0x5355 · 0x696e gwinit died · 0x766d Vm_pageout: VM is full · 554C USB loader defect · Other · System program defective · Controller board defective · Optional board defective$m$, $m$Replace controller firmware 0008 Self-diagnostic Error: CPU: System Call Exception GW 0612 Self-diagnostic Error: CPU: ASIC Interrupt Error GW$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC820$m$, NULL, $m$System program defective$m$, $m$Controller board defective$m$, $m$D · Optional board defective$m$, $m$Replace controller firmware Note: For more details about this SC code error, execute SP5990 to print an SMC report so you can read the error code. The error code is not displayed on the operation panel. For more details about this SC code error, execute SP5990 to print an SMC report so you can read the error code. The error code is not displayed on the operation panel.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC821$m$, $m$D$m$, $m$Self-diagnostics error: ASIC GW$m$, $m$ASIC register check error$m$, $m$A write-verify check occurred in the ASIC. · [0B00] · ASIC device · Controller board defective · ASIC detection error · The I/O ASIC for system control was not detected. · [0B06] Defective ASIC · Defective North Bridge and PCII/F · Controller board defective · For more details about this SC code error, execute SP5990 to print an SMC report so you · can read the error code. The error code is not displayed on the operation panel.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC822$m$, $m$B$m$, $m$Self-diagnostics error: HDD GW$m$, $m$HDD timeout$m$, NULL, $m$Check performed only when HDD is installed: HDD device was busy for over 31 seconds. Service Call A diagnostic command was set for the HDD, but the device Conditions remained busy for over 6 seconds. [3003] Defective HDD device Defective HDD connector Defective ASIC device Replace or uninstall the HDD device. Replace the HDD connector. Replace the controller board. Diagnostics command error Diagnostic command issued an error. [3004] Defective HDD device Replace or remove the HDD device. HDD timeout (First machine) HDD device was busy for over 31 seconds, or Mandolin was not detected. A diagnostic command is set for the HDD, but the device remains was busy for over 6 seconds. [3013] Defective HDD device Defective HDD connector Defective ASIC device Replace or remove the HDD device. Replace the HDD connector Replace the controller board Diagnostics command error (First machine) Diagnostic command issued an error because Mandolin was not [3014] detected, or there was a w/r/c error in the HDD register Defective HDD device Replace the HDD device.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC823$m$, $m$B$m$, $m$Self-diagnostics error: NIC$m$, $m$MAC address check sum error$m$, $m$The result of the MAC address check sum did not match the check sum · stored in ROM. · [6101] · Defective SEEP ROM · Defective I2C bus (connection)$m$, $m$Replace the controller board PHY IC error The PHY IC on the controller was not recognized. [6104] Defective PHY chip Defective ASIC MII I/F Replace the controller board PHY IC loop-back error An error occurred during the loop-back test for the PHY IC on the controller. [6105] Defective PHY chip Defective MAC of ASIC (SIMAC/COMIC/CELLO) Defective I/F with the PHY board Defective soldered connection on the PHY board Replace the controller board$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC824$m$, $m$D$m$, $m$Self-diagnostics error: NVRAM (resident) GW$m$, $m$NVRAM verify error$m$, $m$No NVRAM installed or NVRAM is damaged. · No NVRAM device · [1401] Damaged NVRAM device Service Call · NVRAM backup battery exhausted Conditions · NVRAM socket damaged$m$, $m$Replace the NVRAM$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC829$m$, $m$D$m$, $m$Self-diagnostic Error: Optional RAM$m$, $m$The optional RAM returned an error during the self-diagnostic test.$m$, NULL, $m$Replace the optional memory board Controller board defective For more details about SC 833, SC834 and other errors, execute SP5990 to print an SMC report so you can read the error code. The error code is not displayed on the operation panel. The additional error codes (0F30, 0F31, etc. are listed in the SMC report.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC833$m$, $m$D$m$, $m$Self-diagnostic error: Engine I/F ASIC GW$m$, $m$ASIC (Mandolin) for engine control could not be detected. After the PCI was configured, the device ID for the ASIC could not be checked. [0F30] Defective ASIC (Mandolin) for system control$m$, $m$Defective North Bridge and AGPI/F$m$, $m$Replace the motherboard (engine I/F board). Could not initialize or read the bus connection. Defective connection bus [50B1] Defective SSCG Replace the motherboard (engine I/F board). SSCG register value was incorrect. Defective connection bus [50B2] Defective SSCG Replace the motherboard (engine I/F board).$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC834$m$, $m$D$m$, $m$Self-diagnostic error: optional memory GW$m$, $m$An error occurred after write/verify check for optional RAM on the motherboard..$m$, $m$[5101] · Defective memory device$m$, $m$Replace the motherboard (engine I/F board).$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC838$m$, $m$D$m$, $m$Self-diagnostic error: Clock generator GW$m$, $m$A verify error occurred when setting data was read from the clock generator via the I2C bus$m$, $m$Defective clock generator · [2701] Defective I2C bus · Defective I2C port on the CPU$m$, $m$Replace the controller board. EEPROM access error GW$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC840$m$, $m$A$m$, $m$read error occurred during I/O processing. The failure of the 3rd$m$, $m$D attempt to read caused this error.$m$, $m$Defective EEPROM Service Call$m$, $m$Replace the EEPROM. EEPROM read error GW$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC841$m$, $m$D$m$, $m$Mirrored data of the EEPROM is different from the original data in$m$, $m$EEPROM. Data in the EEPROM was overwritten for some reason.$m$, $m$Cycle the machine off/on · Nand-Flash updating verification error GW$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC842$m$, $m$A$m$, $m$write error for the module written in Nand-Flash occurred while the$m$, $m$C remote ROM and ROM were being updated.$m$, $m$Damaged Nand-Flash · Cycle the machine off/on · Network I/F error GW$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC850$m$, $m$B$m$, $m$Network not operating.$m$, $m$Cycle the machine off/on$m$, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC851$m$, NULL, $m$IEEE 1394 I/F error$m$, $m$Driver setting incorrect and cannot be used by the 1394 I/F.$m$, $m$B · NIB (PHY), LINK module defective; change the Interface Board · Controller board defective · Bluetooth device connection error GW$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC853$m$, NULL, $m$The Bluetooth interface unit was installed while the machine was turned$m$, $m$on.$m$, $m$B · Cycle the machine off/on$m$, $m$Confirm that the Bluetooth interface unit was installed correctly. Cycle the machine off/on again. Bluetooth device removed GW$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC854$m$, NULL, $m$The Bluetooth interface unit was removed while the machine was$m$, $m$turned on.$m$, $m$B · Cycle the machine off/on$m$, $m$Confirm that the Bluetooth interface unit was installed correctly. Cycle the machine off/on again. Hardware Problem:wireless LAN board GW The wireless LAN board can be accessed, but an error was detected.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC855$m$, $m$B$m$, $m$Loose connection$m$, $m$Defective wireless LAN board$m$, NULL, $m$Check wireless LAN card connection Replace wireless LAN board USB I/F Error 1 GW$m$, NULL, NULL);
INSERT INTO manual_entries (manual_id, type, code, level, title, detection, causes, solution, description, setting) VALUES
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC857$m$, $m$D$m$, $m$The USB driver is unstable and caused an error. The USB I/F cannot$m$, $m$be used.$m$, $m$USB board or controller board defective · Data encryption conversion error GW Conditions$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC858$m$, NULL, $m$B$m$, $m$These are errors of the HDD Data Encryption Option D377.$m$, $m$00 Key Acquisition · Key could be acquired.$m$, $m$Replace the controller board 01 HDD Key Setting Error The key was acquired but the HDD could not be set. Turn the machine power off/on several times. Replace the controller board. 02 NVRAM Read Error NVRAM data conversion failed (mismatch with nvram.conf) Replace the NVRAM 30 NVRAM Before Replace Error DFU May occur during development. Turn the machine power off/on several times. Replace the controller board. 31 Other Error An unexpected error occurred while data was being converted. This error is the same as SC991. See SC991 below. Data encryption conversion errors GW$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC859$m$, NULL, $m$B$m$, $m$Data encryption on the HDD failed.$m$, $m$01 HDD encrypted data restoration error · Data could not be restored after encryption. · HDD connection loose, broken, defective · Format HDD · HDD defective · 02 Power interrupt error · Power supply was interrupted during data encryption. · Cycle the machine off/on · 08 HDD Check Error · Data conversion was attempted with no HDD unit present.$m$, $m$Confirm that HDD unit installed correctly Initialize HDD with SP5832-1 Note: After installation, a new HDD should be formatted with SP5832-1 09 Power Loss During Data Conversion Data conversion stopped before NVRAM/HDD data was converted. Format HDD with SP5832-1 10 Data Read Command Error More than two illegal DMAC communications were returned. HDD defective Format HDD with SP5832-1 Replace HDD HDD startup error at power on GW$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC860$m$, $m$B$m$, $m$HDD is connected but a driver error is detected. The driver did not$m$, $m$respond with the status of the HDD within 30 sec.$m$, $m$HDD is not initialized · Level data is corrupted Service Call · Initialize the HDD with SP5-832-001. Conditions · HDD is defective · HDD Error 2: HDD Startup GW · The hard disks were detected at power on, but the disks were not · detected within 30s after recovery from the energy conservation mode.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC861$m$, $m$B$m$, $m$Cable between the hard disks and controller board disconnected$m$, $m$or loose$m$, $m$Hard disk power connector loose · One of the hard disks is defective · Controller defective · Bad sector overflow GW$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC862$m$, NULL, $m$D$m$, $m$There more 100 bad sectors in image storage area of the HDD.$m$, $m$Format HDD with SP4911-2 · HDD defective · HDD data read failure GW$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC863$m$, $m$D$m$, $m$The data written to the HDD cannot be read normally, due to bad$m$, $m$sectors generated during operation.$m$, $m$HDD defective · Controller defective · Note: If the bad sectors are generated at the image partition, the bad · sector information is written to NVRAM, and the next time the HDD is · accessed, these bad sectors will not be accessed for read/write · operation. · HDD data CRC error GW$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC864$m$, $m$D$m$, $m$During HDD operation, the HDD cannot respond to a CRC error query.$m$, $m$Data transfer did not execute normally while data was being written to the HDD.$m$, $m$Format HDD · HDD defective · HDD access error GW$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC865$m$, NULL, $m$D$m$, $m$An error was detected during operation of the HDD. HDD defective.$m$, $m$SD card authentication error GW · A correct license was not found in the SD card. · 866 B Wrong type of SD card · SD card data is corrupted. · Used correct SD card$m$, $m$Replace SD card$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC867$m$, $m$D$m$, $m$No SD card$m$, $m$When the machine was turned on, there was no SD card in the boot slot. Service Call$m$, $m$Insert the SD card · Cycle the machine off/on · SD card access error GW$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC868$m$, NULL, $m$D$m$, $m$An error occurred while an SD card was used.$m$, $m$SD card not inserted correctly · SD card defective · Controller board defective · Address book error GW · Address book data stored on the hard disk was detected as abnormal · when it was accessed from either the operation panel or the network.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC870$m$, NULL, $m$Defective software program$m$, $m$Defective HDD$m$, $m$Incorrect path to the server · B Incorrect encryption setting or encryption key · Damaged address book data · Mount the media that stores the address book data · Cycle the machine off/on. · Initialize the address book data with SP5-846-050. · Cycle machine off/on, and then do SP5-832-006.$m$, $m$Replace the HDD. HDD mail RX data error GW An HDD error was detected immediately after power on. The HDD may be defective or the machine was accidentally$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC872$m$, $m$D$m$, $m$powered off while the HDD was being accessed.$m$, $m$Cycle the machine off/on$m$, $m$Reformat the HDD with SP5832-7 (Mail RX Data)$m$, $m$Replace the HDD HDD mail TX error GW$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC873$m$, $m$D$m$, $m$An error was detected on the HDD immediately after the machine was$m$, $m$turned on, or power was turned of while the machine used the HDD. Do SP5832-007 to format the HDD. HDD defective.$m$, $m$Delete all error 1 (DOS) GW$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC874$m$, $m$A$m$, $m$data error was detected for the HDD/NVRAM after the "Delete All"$m$, $m$option was used. Note: The source of this error is the Data Overwrite Security Unit D$m$, $m$running from an SD card. · Cycle the machine off/on.$m$, $m$Confirm that DOS has been enabled with SP5878.. HDD defective. Delete al error 2: Data area GW$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC875$m$, $m$D$m$, $m$An error occurred while the machine deleted data from the HDD$m$, $m$Note: The source of this error is the Data Overwrite Security Unit running from an SD card.$m$, $m$Cycle the machine off/on · Log Data Error GW$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC876$m$, $m$D$m$, $m$An error was detected in the handling of the log data at power on or$m$, $m$during machine operation. This can be caused by switching the machine off while it is operating.$m$, $m$Log Data Error 1 · 01 Damaged log data file in the HDD Conditions · Initialize the HDD with SP5-832-004. · Log Data Error 2 · An encryption module not installed$m$, $m$Replace or set again the encryption module. Disable the log encryption setting with SP9-730-004 ("0" is off.). Log Data Error 3 Invalid log encryption key due to defective NVRAM data Initialize the HDD with SP5-832-004. Disable the log encryption setting with SP9-730-004 ("0" is off.) Log Data Error 4 04 Unusual log encryption function due to defective NVRAM data Initialize the HDD with SP5-832-004. Log Data Error 5 Installed NVRAM or HDD which is used in another machine. Reinstall the previous NVRAM or HDD. Initialize the HDD with SP5-832-004. Log Data Error 99 99 Other than the above causes Ask your supervisor. Data Overwrite Security error GW$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC877$m$, $m$B$m$, $m$An error occurred, preventing successful execution of the Data$m$, $m$Overwrite Security function, even though it has been enabled with SP5898..$m$, $m$Cycle the machine off/on$m$, $m$Replace NVRAM$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC878$m$, $m$D$m$, $m$Chip errors GW$m$, $m$00 TPM electronic recognition error$m$, $m$01 USB flash error · 02 TPM error · 03 TCSD error · Incorrect updating for the system firmware · Incorrect operating of the USB flash · Defective flash ROM on the controller board$m$, $m$Replace the controller board. File Format Converter Error (MLB) GW$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC880$m$, $m$A$m$, $m$request for access to the file format converter board (MLB) was not$m$, $m$D$m$, $m$answered within the specified time. · Board defective · Authentication area error GW$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC881$m$, $m$D$m$, $m$Authentication application error is detected.$m$, $m$Error data in an authentication application reaches the management limit.$m$, NULL, $m$Turn the main power switch off and on. Software performance error GW If the processing program shows abnormal performance and the program is abnormally ended, this SC is issued.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC899$m$, $m$D$m$, $m$Controller board defective$m$, $m$Software defective Service Call$m$, NULL, $m$Replace the controller board. Turn the main switch off and on. Update the firmware on the controller. Electric counter error GW The total count contains something that is not a number.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC900$m$, NULL, $m$NVRAM incorrect type$m$, $m$NVRAM defective$m$, $m$D NVRAM data scrambled · Unexpected error from external source$m$, $m$Check the connection between the NVRAM and controller. Replace the NVRAM. Replace the controller board.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC901$m$, NULL, $m$Mechanical total counter error$m$, $m$The mechanical counter is not connected.$m$, $m$D · Mechanical total counter defective · Mechanical total counter connector not connected · HDD Status Codes Displayed on Debug Console · Display Meaning · (-1) HDD not connected · (-2) HDD not ready · (-3) No level · (-4) Partition type incorrect · (-5) Error returned during level read or check · (-6) Error returned during level read or check · (-7) "filesystem" repair failed · (-8) "filesystem" mount failed · (-9) Drive does not answer command Service Call · (-10) Internal kernel error Conditions · (-11) Size of drive is too small · (-12) Specified partition does not exist · (-13) Device file does not exist · Recovery Procedure 1 · If the machine returns SC codes for HDD errors (SC860 ~ SC865), please follow the recovery · procedures described for these SC codes. · Recovery Procedure 2 · If the machine does not return one of the five HDD errors (SC860 ~ SC865), turn the machine off · and on. If this does not solve the problem, then initialize the NetFile partition on the HDD with · SP5832 011 (HDD Formatting ± Ridoc I/F). · NetFiles: Jobs printed from the document server using a PC and DeskTopBinder · Before initializing the NetFile partition on the HDD please inform the client that:$m$, $m$1. Received faxes on the delivery server will be lost 2. All captured documents will be lost 3. DeskTopBinder/Print Job Manager/Desk Top Editor job history will be cleared 4. Documents stored on the document server will not be lost. 5. The first time the network accesses the machine, the management information must be reconfigured (this will require a significant amount of time). 6. Execute SP5832 011 then turn the machine off and on. Recovery Procedure 3 If "Procedure 2" does not solve the problem, execute SP5832 001 (HDD Formatting - All), then turn the machine off and on. Executing SP5832 001 erases all document and address book data stored on the hard disks. Be sure to consult with the customer before executing this SP code. Recovery Procedure 4 If "Recovery Procedures 1 to 3" fail to correct the problem, replace the HDD.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC910$m$, NULL, $m$External Controller Error 1$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC911$m$, NULL, $m$External Controller Error 2$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC912$m$, NULL, $m$External Controller Error 3$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC913$m$, $m$B$m$, $m$External Controller Error 4$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC914$m$, NULL, $m$External Controller Error 5$m$, $m$The external controller alerted the machine about an error. For more, refer to the instructions for the external controller.$m$, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC915$m$, NULL, $m$External Controller Error 6$m$, $m$Egret board error$m$, $m$A · The external controller alerted the machine about an error.$m$, $m$Replace the Egret controller board. External Controller Error 6 GW$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC919$m$, NULL, $m$While EAC (External Application Converter), the conversion module,$m$, $m$was operating normally, the receipt of a power line interrupt signal from the FLUTE serial driver was detected, of BREAK signal from B$m$, $m$the other station was detected. · Power outage at the EFI controller. · EFI controller was rebooted. · Connection to EFI controller loose. · Cycle the machine off/on$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC920$m$, NULL, $m$Printer application error GW$m$, $m$00 No response when PM started up 01 Timeout error during PM operation$m$, $m$02 Working memory error · 03 Cannot start filter process Conditions · 04 B Abnormal exit from filter process · An error was detected in the printer application program and · operation cannot continue. · Defective software · Unexpected hardware resource (e.g., memory shortage)$m$, $m$1. Software err, cycle the machine off/on 2. Insufficient memory, add more memory Printer font error GW$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC921$m$, $m$A$m$, $m$necessary font is not found when starting up the printer application.$m$, $m$B$m$, $m$A requested font is not found in the SD card. · Cycle the machine off/on$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC925$m$, $m$B$m$, $m$NetFile function error GW$m$, $m$00 HDD is defective$m$, $m$01 NetFile management file is broken · The NetFile file management on the HDD cannot be used, or a NetFile · management file is corrupted and operation cannot continue. · The HDDs are defective and they cannot be debugged or partitioned, · so the Scan Router functions (delivery of received faxes, document · capture, etc.), Web services, and other network functions cannot be · used. · HDD status codes are displayed below the SC code. · Refer to the four procedures below (Recovery from SC925). · Here is a list of HDD status codes: · Display Meaning · (-1) HDD not connected · (-2) HDD not ready · (-3) No label Conditions · (-4) Partition type incorrect · (-5) Error returned during label read or check · (-6) Error returned during label read or check · (-7) "filesystem" repair failed · (-8) "filesystem" mount failed · (-9) Drive does not answer command · (-10) Internal kernel error · (-11) Size of drive is too small · (-12) Specified partition does not exist · (-13) Device file does not exist · Recovery from SC 925 · Procedure 1 · If the machine shows SC codes for HDD errors (SC860 to SC865) with SC 925, do the recovery · procedures for SC860 to SC865. · Procedure 2 · If the machine does not show one of the five HDD errors (SC860 to SC865), turn the machine · power off and on. If this is not the solution for the problem, then initialize the NetFile partition on · the HDD with SP5832-011 (HDD Formatting ± Ridoc I/F). · NetFiles: Jobs printed from the document server using a PC and DeskTopBinder · Before you initialize the NetFile partition on the HDD, tell the customer that: · Received faxes on the delivery server will be erased · All captured documents will be erased · DeskTopBinder/Print Job Manager/Desk Top Editor job history will be erased · Documents on the document server, and scanned documents, will not be erased. · The first time that the network gets access to the machine, the management information must · be configured again (this will use a lot of time). · Before you initialize the Netfile partition with SP5832-011, do these steps:$m$, $m$1. Go into the User Tools mode and do "Delivery Settings" to print all received fax documents that are scheduled for delivery. Then erase them. 2. In the User Tools mode, do Document Management> Batch Delete Transfer Documents. 3. Do SP5832-011, then turn the machine power off and on. Procedure 3 If "Procedure 2" is not the solution for the problem, do SP5832-001 (HDD Formatting ± All), then turn the machine power off and on. SP5832-001 erases all document and address book data on the hard disks. Ask the customer before you do this SP code. Procedure 4 If "Procedure 3" is not the solution for the problem, replace the HDD.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC953$m$, $m$D$m$, $m$Scanner image setting error$m$, $m$The settings required for image processing using the scanner are not sent from the IPU.$m$, $m$Software defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC954$m$, $m$D$m$, $m$Printer image setting error$m$, $m$The settings required for image processing using the printer controller are not sent from the IPU.$m$, $m$Software defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC955$m$, $m$D$m$, $m$Memory setting error$m$, $m$The settings that are required for image processing using the memory are not sent from the IPU.$m$, $m$Software defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC964$m$, $m$D$m$, $m$Printer ready error$m$, $m$The print ready signal is not generated for more than 17 seconds after the IPU received the print start signal. Service Call$m$, $m$Software defective$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC965$m$, $m$B$m$, $m$Print Start Error$m$, $m$During print processing, another command to start printing was received.$m$, $m$Software bug$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC984$m$, $m$D$m$, $m$Print image data transfer error$m$, $m$After a data transfer begins from the controller to the engine via the PCI bus, the transfer does not end within 15 s.$m$, $m$Controller (SIMAC) board defective · BICU defective · BICU/controller disconnected$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC985$m$, $m$D$m$, $m$Scanned image data transmission error$m$, $m$After a data transfer begins from the engine to the controller via the PCI bus, the transfer does not end within 3 s.$m$, $m$Controller (SIMAC) board defective · BICU defective · BICU/controller disconnected$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC986$m$, $m$D$m$, $m$Software error 1$m$, $m$The write parameter received by the write module at the beginning of the setting table is NULL.$m$, $m$Controller (SIMAC) board defective · BICU defective · BICU/controller disconnected · Software performance error GW · The software makes an unexpected operation.$m$, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC990$m$, $m$D$m$, $m$Defective software$m$, $m$Defective controller$m$, $m$Software error · Cycle the machine off/on.$m$, $m$Reinstall the controller firmware Reinstall the main firmware Software continuity error GW$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC991$m$, NULL, $m$The software has attempted to perform an unexpected operation.$m$, $m$However, unlike SC 990, the object of the error is continuity of the software.$m$, $m$C · Software program error · Internal parameter incorrect · Insufficient working memory · This SC is not displayed on the LCD (logging only). · For more details about SC991:$m$, $m$1. Execute SP7403 or print an SMC Report (SP5990) to read the history of the 10 most recent Service Call logged errors. 2. If you press the zero key on the operation panel with the SP selection menu displayed, you will see detailed information about the recently logged SC991, including the software file name, line number, and so on. Of these two methods, 1) is the recommended method, because another SC could write over the information for the previous SC. Undefined Error (No SC Code) GW$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC992$m$, NULL, $m$An error not controlled by the system occurred (the error does not$m$, $m$come under any other SC code).$m$, $m$C · Software defective$m$, $m$Turn the machine power off and on. The machine cannot be used until this error is corrected. Re-install firmware Operation Panel Management Records Exceeded GW$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC994$m$, $m$C$m$, $m$An error occurred because the number of records exceeded the limit$m$, $m$for images managed in the service layer of the firmware. This can occur if there are too many application screens open on the operation panel. No action required because this SC does not interfere with operation of the machine.$m$, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC995$m$, $m$D$m$, $m$CPM setting error GW$m$, $m$Defective BCU$m$, $m$NVRAM Replacement error · 01 Install the previous NVRAM. · Input the serial number with SP5-811-004, and turn the main · power switch off and on. · Defective NVRAM · Defective controller · 02 Update the controller firmware.$m$, $m$Install a new NVRAM, and turn off and on the main power switch after SC995-002 has occurred. Incorrect type controller installed 03 Defective controller Replace the controller with the correct type. Incorrect model controller installed. Replace the controller with the correct model. Application function selection error GW The application selected by the operation panel key operated abnormally (No response, abnormal ending). Software (including the software configuration) defective An option required by the application (RAM, DIMM, board) is not Service Call installed. Conditions Nesting of the fax group addresses is too complicated.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC997$m$, NULL, $m$B$m$, NULL, NULL, $m$Check the devices necessary for the application program. If necessary devices have not been installed, install them. Check that application programs are correctly configured. For a fax operation problem, simplify the nesting of the fax group addresses. Take necessary countermeasures specific to the application program. If the logs can be displayed on the operation panel, see the logs. Application start error GW No applications start within a specified time after the power is turned on.$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$error$m$, $m$SC998$m$, NULL, $m$Loose connection of RAM-DIMM, ROM-DIMM$m$, $m$Defective controller$m$, $m$Software problem · D$m$, $m$Check the setting of SP5-875-001. If the setting is set to "1 (OFF)", change it to "0 (ON)". Check if the RAM-DIMM and ROM-DIMM are correctly connected. Reinstall the controller system firmware. Replace the controller board. If a problem always occurs in a specific condition (for example. printer driver setting, image file), the problem may be caused by a software error. In such a case, the following data and information need to be sent back to your product specialist. Please understand that it may take some time to get a reply on how to solve the problem, because in some cases the design staff in Japan must analyze the data. Symptom / Possible Causes / Action taken Summary sheet (SP mode "Printer SP", SP1-004 [Print Summary]) SMC - All (SP5-990-001) SMC - Logging (SP5-990-004) Printer driver settings used when the problem occurs All data displayed on the screen (SC code, error code, and program address where the problem is logged.) Image file which causes the problem, if possible$m$, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-001$m$, NULL, $m$Leading Edge Registration$m$, NULL, NULL, NULL, $m$Adjusts the printing leading edge registration using the trimming area pattern (SP2902-003, No.18). [-9 to +9/0/0.1mm] Specification: 3±2mm$m$, $m$[-9 to +9/0/0.1mm]$m$);
INSERT INTO manual_entries (manual_id, type, code, level, title, detection, causes, solution, description, setting) VALUES
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-002-001$m$, NULL, $m$Tray-1$m$, NULL, NULL, NULL, $m$Adjusts printing side-to-side registration for each feed station, using test pattern (SP2902-003, No.18). These SP's should be adjusted after replacing the laser synchronization detector or the laser optical unit.$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-002-002$m$, NULL, $m$Tray-2$m$, NULL, NULL, NULL, NULL, NULL),
