  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-002-005$m$, NULL, $m$By-pass Tray$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-002-006$m$, NULL, $m$LCT$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-002-007$m$, NULL, $m$Duplex Tray$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-003-001$m$, NULL, $m$Tray LCT$m$, NULL, NULL, NULL, $m$Adjusts the registration motor timing. This timing determines the amount of paper buckle at registration. (A higher setting causes more buckling.) [-9 to +9/0/1 mm]$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-003-002$m$, NULL, $m$Duplex Tray$m$, NULL, NULL, NULL, NULL, NULL),
