  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-112$m$, NULL, $m$Auto Process Control$m$, NULL, NULL, NULL, $m$Sets the temperature of the hot roller for auto process control to start. [70 to 150/140/1°C] DFU$m$, $m$[70 to 150/140/1°C]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-159$m$, NULL, $m$Fusing Jam: SC Setting$m$, NULL, NULL, NULL, $m$This SP determines what the machine does if paper jams occur in the fusing unit for three consecutive sheets of paper. 0: (default): A jam alert is shown on the screen. The customer can remove the jam and the machine works normally after that. 1: SC559 occurs. The technician must remove the jam.$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-802-001$m$, NULL, $m$Fusing Web Used Area Display/Setting Displays the percentage of the web consumption in 1% steps (0% to 100%). Mode Tables This setting must be reset to zero after the web is replaced.$m$, NULL, NULL, NULL, NULL, $m$[0 to 120/0/1 %]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-802-002$m$, NULL, $m$Fusing Web Motor Operation Interval Adjusts the interval of copy operation time (seconds) after which the web motor is driven. D131: D132: D133:$m$, NULL, NULL, NULL, NULL, $m$[5 to 50/18/1 s] [5 to 50/15/1 s] [5 to 50/14/1 s]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-802-003$m$, NULL, $m$Label CPM (0:25/1:35/2:40/3:45/4:55) 0: 25 cpm 1: 35 cpm 2: 40 cpm 3: 45 cpm 4: 55 cpm$m$, NULL, NULL, NULL, NULL, $m$[0 to 4/0/1 step]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-802-004$m$, NULL, $m$Web Near End Value Adjusts the timing of the web near end alert by changing the amount of web that has been used before the alert is triggered.$m$, NULL, NULL, NULL, NULL, $m$[0 to 100/80/1 %]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-802-005$m$, NULL, $m$Web Roll Coefficient Determines the coefficient of the web take-up time from cleaning toner from the roller while taking into consideration the take-up time for web buckle. DFU$m$, NULL, NULL, NULL, NULL, $m$[10 to 20/9/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-802-006$m$, NULL, $m$Web Length (0: 20m 1: 22.7m 2:28.5m 3:32m) Set the length of web. D131/b/d: x = 3, D133: x = 2$m$, NULL, NULL, NULL, NULL, $m$[0 to 3 / x /1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-802-007$m$, NULL, $m$Web Motor Counter: Continuous$m$, NULL, NULL, NULL, NULL, $m$[0 to 255/0/1 Step]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-802-008$m$, NULL, $m$Web Motor Counter: Total$m$, NULL, NULL, NULL, NULL, $m$[0 to 255/0/1 Step]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-903-001$m$, NULL, $m$Yes/No This determines whether the web motor is driven at the end of a job. 0: Off 1: On Enable when too much paper dust is causing copies to blacken.$m$, NULL, NULL, NULL, NULL, $m$[0 to 1/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-903-002$m$, NULL, $m$Job End Condition (Continuous PPC Time) At the end of a job, the web motor is driven if the job lasted longer than the value of this SP mode. Only valid if SP1903-001 is set to 'On'.$m$, NULL, NULL, NULL, NULL, $m$[1 to 99/7/1s]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-903-003$m$, NULL, $m$Job End Frequency If the web motor is driven at the end of a job, this SP determines how many times the web motor operation is executed.$m$, NULL, NULL, NULL, NULL, $m$[1 to 5/2/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-904-001$m$, NULL, $m$Calibrates the minimum paper width position of the sensor (100 mm). Move the side fences to the 100 mm position then press Execute. Maximum Size$m$, NULL, NULL, NULL, $m$Minimum Size$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-904-002$m$, NULL, $m$Calibrates the maximum paper width position of the sensor (A3). Move the side fences to the A3 position then press Execute.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-905$m$, NULL, $m$Thick Paper ± By-pass Tray$m$, NULL, NULL, NULL, $m$Adjusts the by-pass feed clutch operation for thick paper. [0 to 1/1/1] 1: On: 30 ms 0: Off: This setting switches the by-pass feed clutch on for 30 ms when the registration motor turns on. It only happens when thick paper is selected, to help this paper pass through the registration rollers.$m$, $m$[0 to 1/1/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-906$m$, NULL, $m$Temperature/Humidity Sensor$m$, NULL, NULL, NULL, $m$Temperature Sensor Service$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-907-001$m$, NULL, $m$Thick Mode (1:ON/0:OFF) Thick Paper Normal Size$m$, NULL, NULL, NULL, $m$Pre-fusing idling: The hot roller turns freely to increase its temperature before thick paper or OHP goes through the fusing unit. [0 to 1/1/1] 0: Pre-fusing idling is not done. 1: The fusing motor turns the hot roller with no paper in the fusing unit. This ensures that the hot roller reaches the correct temperature. It is only done for thick paper or OHP. In this mode, the paper stops at the registration roller, then roller resumes its rotation after the hot roller reaches the correct temperature.$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP1-907-002$m$, NULL, $m$Thick Mode: Small Paper Size (1:ON/0:OFF) Thick Paper Small Size$m$, NULL, NULL, NULL, NULL, NULL),
